{"packet_id":"D067-03","doc_id":"D067","jurisdiction":"NJ","category":"just_cause_eviction","lifecycle":"enacted","title":"New Jersey Anti-Eviction Act statutory eviction grounds","requirement":"A landlord may evict only for a statutory ground, such as nonpayment of rent, disorderly conduct, damage, lease violations, retirement of the property or condominium conversion, and must serve the required notice.","key_value":null,"coverage_conditions":"Most residential rentals: single-family homes, mobile homes and mobile home park land, apartment buildings, complexes, rooming and boarding homes.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":true,"other":"Hotel/motel guests covered only if the occupant has no alternate residence and resides there continually."},"exemptions":"Two- or three-unit owner-occupied premises with two or fewer rental units; transient hotel, motel or guest-house guests and seasonal tenants; a unit held in trust for a developmentally disabled immediate family member who permanently occupies it.","penalty":null,"effective_date":null,"citation":"N.J.S.A. 2A:18-61.1","quoted_span":"Listed below are the statutory grounds for eviction as set forth in the Anti-Eviction Statute. A. Failure to Pay Rent If a tenant fails to pay rent, the landlord may immediately take legal action to have the tenant evicted.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D067-03","doc_id":"D067","jurisdiction":"NJ","category":"just_cause_eviction","lifecycle":"enacted","title":"New Jersey self-help eviction and lockout ban","requirement":"A landlord may not enter and remove tenants without their consent or a court judgment; padlocking, disconnecting utilities or blocking entry while the tenant still lives there is an illegal eviction.","key_value":null,"coverage_conditions":"All residential rental dwellings in New Jersey; the prohibition applies under any circumstances.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"Only a court officer may physically evict a tenant after a warrant for removal."},"exemptions":null,"penalty":"A tenant evicted by forcible entry and detainer may recover possession and all damages, including court costs and reasonable attorney fees; the landlord may be charged with disorderly conduct.","effective_date":null,"citation":"N.J.S.A. 2A:39-1","quoted_span":"Self-help evictions, or lockouts, made by the landlord are illegal in New Jersey.","interaction":null,"confidence":0.8,"conflict_flag":false,"conflict_note":null}
